#include <iostream>

// The machine program, one instruction per line:
//   mov eax, 4      copy 4 into eax
//   mov ebx, 10     copy 10 into ebx
//   add eax, ebx    eax becomes eax + ebx
//   add eax, eax    eax becomes eax + eax
int main() {
    std::cout << "mov eax, 4   -> eax=4 ebx=0" << '\n';
    std::cout << "mov ebx, 10  -> eax=4 ebx=10" << '\n';
    std::cout << "add eax, ebx -> eax=14 ebx=10" << '\n';
    std::cout << "add eax, eax -> eax=28 ebx=10" << '\n';
    return 0;
}

