#include <iostream>

// The machine program, one instruction per line:
//   mov eax, 7      copy 7 into eax
//   mov ebx, 3      copy 3 into ebx
//   sub eax, ebx    eax becomes eax - ebx
//   add ebx, eax    ebx becomes ebx + eax
//   add eax, ebx    eax becomes eax + ebx
int main() {
    std::cout << "mov eax, 7   -> eax=7 ebx=0" << '\n';
    std::cout << "mov ebx, 3   -> eax=7 ebx=3" << '\n';
