example.code:
// #include pastes in what the program needs to use std::cout.
#include <iostream>

// The startup code calls main once the kernel has created the process.
int main() {
    // std::cout collects the text and asks the kernel to write it.
    std::cout << "Hello" << '\n';
    std::cout << "Goodbye" << '\n';
    // return ends main and hands 0 to the kernel as the exit status.
    return 0;
    std::cout << "never printed" << '\n';
}

