    std::cout << "chars per line: " << 64 / sizeof('A') << '\n';
    std::cout << "whole numbers per line: " << 64 / sizeof(42) << '\n';
    std::cout << "decimals per line: " << 64 / sizeof(2.5) << '\n';
    return 0;
}

